// ДЕТЕРМИНИРОВАННЫЙ расчёт цены по правилам из БД. LLM число НЕ трогает.
const rules = $input.all().map(i => i.json);
const inp = $('▶️ Вход: lead_id + анкета').first().json;
const a = inp.answers || {};
const find = (t, f, c) => rules.find(x => x.rule_type === t && x.factor === f && (c === undefined || x.condition === c));
const num = v => v == null ? null : Number(v);
const base = num((find('base','base', a.audit_type) || {}).value);
if (base == null) throw new Error('Неизвестный вид аудита: ' + a.audit_type);
const revM = num((find('multiplier','revenue_band', a.revenue_band) || {}).value) ?? 1;
const empM = num((find('multiplier','employees', a.employees) || {}).value) ?? 1;
const stdM = num((find('multiplier','standard', a.standard) || {}).value) ?? 1;
const urgency = (Number(a.deadline_days) > 0 && Number(a.deadline_days) < 30) ? 'urgent' : 'normal';
const urgM = num((find('multiplier','urgency', urgency) || {}).value) ?? 1;
const years = Math.max(1, parseInt(a.years) || 1);
const entities = Math.max(1, parseInt(a.entities) || 1);
const extraYear = num((find('additive','extra_year') || {}).value) ?? 0.8;
const extraEntity = num((find('additive','extra_entity') || {}).value) ?? 0.2;
const cfg = f => num((find('config', f) || {}).value);
const subtotal = base * revM * empM * stdM * urgM;
const scopeAdd = base * extraYear * (years - 1) + base * extraEntity * Math.min(entities - 1, 5);
const roundTo = cfg('round_to') || 50000;
let price = Math.round((subtotal + scopeAdd) / roundTo) * roundTo;
const floor = cfg('floor') || 0;
if (price < floor) price = floor;
const threshold = cfg('review_threshold');
const needs_review = threshold != null && price > threshold;
const labels = { statutory: 'обязательный аудит', voluntary: 'инициативный аудит', subsoil: 'аудит недропользователя', tax: 'налоговый аудит', due_diligence: 'due diligence / спецзадание' };
const fmt = n => Math.round(n).toLocaleString('ru-RU') + ' ₸';
const breakdown = { base, audit_type: a.audit_type, revenue_mult: revM, employee_mult: empM, standard_mult: stdM, urgency, urgency_mult: urgM, years, entities, subtotal: Math.round(subtotal), scope_add: Math.round(scopeAdd), floor, round_to: roundTo, review_threshold: threshold };
return [{ json: { lead_id: inp.lead_id, chat_id: inp.chat_id, answers: a, service_code: a.audit_type, service_label: labels[a.audit_type] || a.audit_type, price, price_formatted: fmt(price), currency: 'KZT', breakdown, needs_review } }];

// LLM ТОЛЬКО ФОРМУЛИРУЕТ текст КП вокруг уже посчитанной цены.
const d = $json;
const a = d.answers || {};
const system = 'Ты — менеджер аудиторской компании. Пишешь короткое коммерческое предложение (КП) клиенту в чат: дружелюбный деловой тон, на русском, без markdown и без таблиц, 6-10 предложений. НИКОГДА не меняй и не пересчитывай цену — используй её ровно как передана. Не упоминай технические названия полей. Структура: приветствие по имени компании; что входит в услугу; срок; итоговая стоимость; что дальше (подтвердить — и пришлём договор на электронную подпись).';
const user = 'Данные для КП. Компания: ' + (a.company_name || 'клиент') + '. Контакт: ' + (a.contact_name || '') + '. Услуга: ' + d.service_label + '. Стандарт отчётности: ' + (a.standard === 'ifrs' ? 'МСФО' : 'НСФО') + '. Периодов (лет): ' + (a.years || 1) + '. Юрлиц: ' + (a.entities || 1) + '. Желаемый срок: ' + (a.deadline_days || '—') + ' дней' + (d.breakdown.urgency === 'urgent' ? ' (срочно)' : '') + '. ИТОГОВАЯ ЦЕНА: ' + d.price_formatted + ' (использовать ровно эту сумму). Допконтекст от клиента: ' + (a.notes || 'нет') + '.';
return [{ json: { ...d, body: JSON.stringify({ model: 'llama-3.3-70b-versatile', temperature: 0.3, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] }) } }];

const meta = $('🧠 Запрос: текст КП').first().json;
let text = $json.choices?.[0]?.message?.content || '';
text = String(text).replace(/```/g, '').trim();
if (!text) text = 'Коммерческое предложение: ' + meta.service_label + '. Стоимость: ' + meta.price_formatted + '. Подтвердите — и мы направим договор на электронную подпись.';
return [{ json: { lead_id: meta.lead_id, chat_id: meta.chat_id, service_code: meta.service_code, service_label: meta.service_label, price: meta.price, price_formatted: meta.price_formatted, currency: meta.currency, breakdown: meta.breakdown, needs_review: meta.needs_review, proposal_text: text } }];
